(function(){
  var IDX=window.__KIYO_IDX||[];
  var css=document.createElement('style');
  css.textContent='#ksrch{position:fixed;top:10px;right:60px;z-index:60;width:172px;font-family:"Noto Sans TC",sans-serif}'
   +'#ksrch .kin{width:100%;padding:8px 12px 8px 32px;border-radius:20px;border:1px solid rgba(240,194,60,.5);background:rgba(18,10,4,.92);color:#fbf0d6;font-size:.84rem;outline:none;box-shadow:0 2px 10px rgba(0,0,0,.4)}'
   +'#ksrch .kin::placeholder{color:#a88c60}'
   +'#ksrch .kic{position:absolute;left:11px;top:9px;color:#f0c23c;font-size:.9rem;pointer-events:none}'
   +'#ksrch .kres{position:absolute;top:40px;right:0;width:270px;max-height:60vh;overflow-y:auto;background:rgba(18,10,4,.98);border:1px solid rgba(240,194,60,.4);border-radius:10px;box-shadow:0 12px 30px -8px rgba(0,0,0,.8);display:none;padding:6px}'
   +'#ksrch .kres a{display:block;padding:9px 12px;color:#ddc9a2;font-size:.86rem;border-radius:6px;text-decoration:none;line-height:1.5}'
   +'#ksrch .kres a:hover{background:rgba(255,122,30,.14);color:#ffe488}'
   +'#ksrch .kres a b{color:#f0c23c}'
   +'#ksrch .kno{padding:12px;color:#a88c60;font-size:.84rem;text-align:center}'
   +'@media(max-width:1180px){#ksrch{top:auto;bottom:14px;right:14px;width:150px}#ksrch .kres{top:auto;bottom:42px}}';
  document.head.appendChild(css);
  var box=document.createElement('div'); box.id='ksrch';
  box.innerHTML='<span class="kic">🔍</span><input class="kin" type="text" placeholder="搜尋..." aria-label="站內搜尋"><div class="kres"></div>';
  document.body.appendChild(box);
  var inp=box.querySelector('.kin'), res=box.querySelector('.kres');
  function esc(s){return s.replace(/[&<>]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})}
  inp.addEventListener('input',function(){
    var q=this.value.trim().toLowerCase();
    if(!q){res.style.display='none';res.innerHTML='';return;}
    var hits=[];
    for(var i=0;i<IDX.length;i++){
      var o=IDX[i]; var x=o.x.toLowerCase(); var ti=o.t.toLowerCase();
      var score=ti.indexOf(q)>=0?2:(x.indexOf(q)>=0?1:0);
      if(score)hits.push([score,o]);
    }
    hits.sort(function(a,b){return b[0]-a[0]});
    hits=hits.slice(0,12);
    if(!hits.length){res.innerHTML='<div class="kno">查無「'+esc(q)+'」</div>';res.style.display='block';return;}
    res.innerHTML=hits.map(function(h){return '<a href="'+h[1].u+'"><b>'+esc(h[1].t)+'</b></a>'}).join('');
    res.style.display='block';
  });
  document.addEventListener('click',function(e){if(!box.contains(e.target))res.style.display='none'});
})();
